const defaultSave=()=>({highScore:0,totalCoins:0,unlockedSkins:['18bro'],equippedSkin:'18bro',completedMissions:[],settings:{music:false,sfx:true,quality:DEFAULT_PICTURE_MODE,modelSet:DEFAULT_MODEL_SET,fontStyle:DEFAULT_FONT_STYLE,reducedMotion:false},records:[],introSeen:false,totalChips:0,totalPowers:0,runs:0,bestDistance:0,bestChips:0,bestCoins:0,bestDodges:0});
function loadSave(){try{const d=JSON.parse(localStorage.getItem(STORE_KEY));if(!d||typeof d!=='object')return defaultSave();const s={...defaultSave(),...d,settings:{...defaultSave().settings,...d.settings}};for(const k of ['highScore','totalCoins','totalChips','totalPowers','runs','bestDistance','bestChips','bestCoins','bestDodges'])s[k]=Math.max(0,Math.floor(Number(s[k])||0));s.unlockedSkins=Array.isArray(s.unlockedSkins)?s.unlockedSkins.filter(k=>skinDefs.some(x=>x.id===k)):['18bro'];if(!s.unlockedSkins.includes('18bro'))s.unlockedSkins.push('18bro');if(!s.unlockedSkins.includes(s.equippedSkin))s.equippedSkin='18bro';s.records=Array.isArray(s.records)?s.records.filter(r=>r&&Number.isFinite(r.score)&&Number.isFinite(r.distance)).slice(0,8):[];s.completedMissions=Array.isArray(s.completedMissions)?s.completedMissions:[];s.settings.music=false;s.settings.quality=normalizePictureMode(s.settings.quality);s.settings.fontStyle=normalizeFontStyle(s.settings.fontStyle);return normalizeCustom(s);}catch{return normalizeCustom(defaultSave());}}
let save=normalizeCustom(loadSave()), storageOK=true, muted=false, practice=false, banked=false, runPowers=0, runId=0, fps=60, toastTime=0,bannerTime=0,pursuitRewardTime=0,scoreBonusTime=0,powerPickupTime=0,hudClock=0,frame=0,themeOverride=null,resultSequence=null;
save.settings.modelSet=normalizeModelSet(save.settings.modelSet);
